// Generated by npm run build:vscode.
const vscode = require('vscode');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const STYLESHEET = "arcubic-vscode.css";
const BUNDLED = 'arcubic-vscode.css';
const STYLESHEET_UPDATED = "Arcubic updated its interface styles. Apply them now?";
const APPLY = "Apply";

// Custom UI Style's path variables: ${userHome} and ${env:NAME:fallback}.
const expand = value => value
  .replace(/\$\{userHome\}/g, os.homedir())
  .replace(/\$\{env:([^:}]+)(?::([^}]*))?\}/g, (_, name, fallback = '') => process.env[name] ?? fallback);

function importedCopies() {
  const imports = vscode.workspace.getConfiguration('custom-ui-style').get('external.imports') ?? [];
  return imports
    .filter(entry => typeof entry === 'string' && entry.startsWith('file://'))
    .map(entry => vscode.Uri.parse(expand(entry)).fsPath)
    .filter(file => path.basename(file) === STYLESHEET);
}

function isCurrent(file, current) {
  try { return fs.readFileSync(file, 'utf8') === current; } catch { return false; }
}

async function activate(context) {
  const current = fs.readFileSync(path.join(context.extensionPath, BUNDLED), 'utf8');
  const outdated = importedCopies().filter(file => !isCurrent(file, current));
  if (!outdated.length) return;
  for (const file of outdated) {
    fs.mkdirSync(path.dirname(file), {recursive: true});
    fs.writeFileSync(file, current);
  }
  if (await vscode.window.showInformationMessage(STYLESHEET_UPDATED, APPLY) === APPLY) {
    await vscode.commands.executeCommand('custom-ui-style.reload');
  }
}

module.exports = {activate, deactivate() {}};
